  "test": "import os
from types import SimpleNamespace
import pytest

from langfuse.span_filter import is_known_llm_instrumentor


def test_extra_prefixes_via_env(monkeypatch):
    # Set extra prefixes in environment
    monkeypatch.setenv("LANGFUSE_EXTRA_INSTRUMENTATION_PREFIXES", "mycustom,another.prefix")

    span_custom = SimpleNamespace(instrumentation_scope=SimpleNamespace(name="mycustom.scope"))
    assert is_known_llm_instrumentor(span_custom) is True

    span_another = SimpleNamespace(instrumentation_scope=SimpleNamespace(name="another.prefix.extra"))
    assert is_known_llm_instrumentor(span_another) is True

    # A scope not in base or extra list should remain False
    span_unknown = SimpleNamespace(instrumentation_scope=SimpleNamespace(name="unknown"))
    assert is_known_llm_instrumentor(span_unknown) is False"
